import { useCallback, useState } from 'react';
import {
  JxStack,
  JxCard,
  JxHeading,
  JxText,
  JxBadge,
  JxSegmentedControl,
  JxSlider,
  JxSwitch,
  JxDivider,
  JxSelect,
} from '@jinx-ui/react';

type Theme = 'light' | 'dark' | 'system';
type Font = 'system' | 'inter' | 'mono';

export interface AppearanceSettings {
  theme: Theme;
  scale: number;
  dense: boolean;
  font: Font;
}

interface AppearanceSettingsScreenProps {
  onChange?: (settings: AppearanceSettings) => void;
}

const themeLabels: Record<Theme, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

const fontOptions: { value: Font; label: string }[] = [
  { value: 'system', label: 'Системный' },
  { value: 'inter', label: 'Inter' },
  { value: 'mono', label: 'Моноширинный' },
];

export default function AppearanceSettingsScreen({ onChange }: AppearanceSettingsScreenProps) {
  const [theme, setTheme] = useState<Theme>('system');
  const [scale, setScale] = useState(100);
  const [dense, setDense] = useState(false);
  const [font, setFont] = useState<Font>('system');

  const emit = useCallback(
    (next: Partial<AppearanceSettings>) => {
      onChange?.({ theme, scale, dense, font, ...next });
    },
    [theme, scale, dense, font, onChange]
  );

  const handleThemeChange = (value: Theme) => {
    setTheme(value);
    emit({ theme: value });
  };

  const handleScaleChange = (value: number) => {
    setScale(value);
    emit({ scale: value });
  };

  const handleDenseChange = (value: boolean) => {
    setDense(value);
    emit({ dense: value });
  };

  const handleFontChange = (value: Font) => {
    setFont(value);
    emit({ font: value });
  };

  return (
    <JxCard className="jx-p-6">
      <JxStack direction="column" gap="6">
        <JxStack direction="row" align="center" justify="between">
          <JxHeading level={2}>Внешний вид</JxHeading>
          <JxBadge variant="neutral">{themeLabels[theme]}</JxBadge>
        </JxStack>

        <JxStack direction="column" gap="2">
          <JxText size="sm" weight="medium">
            Тема
          </JxText>
          <JxSegmentedControl
            value={theme}
            onValueChange={(value) => handleThemeChange(value as Theme)}
            aria-label="Тема оформления"
          >
            <JxSegmentedControl.Item value="light">Светлая</JxSegmentedControl.Item>
            <JxSegmentedControl.Item value="dark">Тёмная</JxSegmentedControl.Item>
            <JxSegmentedControl.Item value="system">Системная</JxSegmentedControl.Item>
          </JxSegmentedControl>
        </JxStack>

        <JxStack direction="column" gap="2">
          <JxStack direction="row" align="center" justify="between">
            <JxText size="sm" weight="medium">
              Масштаб интерфейса
            </JxText>
            <JxText size="sm" tone="muted">
              {scale}%
            </JxText>
          </JxStack>
          <JxSlider
            value={scale}
            onValueChange={handleScaleChange}
            min={80}
            max={140}
            step={5}
            aria-label="Масштаб интерфейса"
          />
        </JxStack>

        <JxStack direction="row" align="center" justify="between">
          <JxStack direction="column" gap="1">
            <JxText size="sm" weight="medium">
              Плотная вёрстка
            </JxText>
            <JxText size="sm" tone="muted">
              Сократить отступы между элементами
            </JxText>
          </JxStack>
          <JxSwitch value={dense} onValueChange={handleDenseChange} aria-label="Плотная вёрстка" />
        </JxStack>

        <JxDivider />

        <JxStack direction="column" gap="3">
          <JxText size="sm" weight="medium" tone="muted">
            Ещё
          </JxText>
          <JxStack direction="column" gap="2">
            <JxText size="sm" weight="medium">
              Шрифт
            </JxText>
            <JxSelect
              value={font}
              onValueChange={(value) => handleFontChange(value as Font)}
              aria-label="Шрифт интерфейса"
            >
              {fontOptions.map((option) => (
                <JxSelect.Option key={option.value} value={option.value}>
                  {option.label}
                </JxSelect.Option>
              ))}
            </JxSelect>
          </JxStack>
        </JxStack>
      </JxStack>
    </JxCard>
  );
}

